11	use AtrioTeam\DigitalHub\Tags\Models\TagGroup;
12	use Illuminate\Console\Command;
13	use Illuminate\Support\Facades\DB;
14	use Illuminate\Support\Str;
15	use OpenSpout\Reader\XLSX\Reader;
16	
17	/**
18	 * Import dei tag anagrafica dei materiali dal foglio "Materiali" del file
19	 * filtri INTERIOR (`INTERIOR - materiali e tessuti filtri.xlsx`).
20	 *
21	 * Il foglio è a colonna singola: righe intestazione di blocco (Tipologia,
22	 * Finitura, Colore) seguite dai valori; le righe separatore (`____`) e vuote
23	 * vengono ignorate.
24	 *
25	 * Ogni blocco diventa una TagCategory (identificata dallo slug) dentro il
26	 * gruppo "Filtri Materiali Indoor" (entity_type=material, target=entity,
27	 * Category1 Indoor), ogni valore un Tag della categoria. Idempotente: il
28	 * matching dei tag esistenti è per nome normalizzato (case-insensitive,
29	 * ignora i suffissi tra parentesi, es. "Lucido (Glossy)" ≡ "Lucido") e i
30	 * tag già presenti non vengono rinominati, così le traduzioni curate in
31	 * admin sopravvivono ai rilanci.
32	 */
33	class ImportIndoorFiltriMateriali extends Command
34	{
35	    protected $signature = 'app:import-indoor-filtri-materiali '
36	        . '{--file=storage/app/private/import/indoor/materiali-tessuti/INTERIOR - materiali e tessuti filtri.xlsx} '
37	        . '{--fresh : Svuota i tag delle categorie interessate prima di reimportare}';
38	
39	    protected $description = 'Import dei tag anagrafica materiali dal file filtri INTERIOR (foglio "Materiali")';
40	
41	    private const SHEET = 'Materiali';
42	
43	    /**
44	     * Intestazioni di blocco (chiave normalizzata) → nome visualizzato della
45	     * TagCategory. Nel foglio compaiono con casing misto (es. "FINITURA").
46	     *
47	     * @var array<string, string>
48	     */
49	    private const BLOCKS = [
50	        'tipologia' => 'Tipologia',
51	        'finitura' => 'Finitura',
52	        'colore' => 'Colore',
53	    ];
54	
55	    public function handle(): int
56	    {
57	        $file = (string) $this->option('file');
58	        if (! is_file($file)) {
59	            $this->error("File non trovato: {$file}");
60	
61	            return self::FAILURE;
62	        }
63	
64	        $blocks = $this->parseSheet($file);
65	        if ($blocks === null) {
66	            $this->error('Foglio "' . self::SHEET . '" non trovato nel file.');
67	
68	            return self::FAILURE;
69	        }
70	
71	        $stats = ['categories' => 0, 'tags' => 0];
72	
73	        DB::transaction(function () use ($blocks, &$stats): void {
74	            $group = $this->resolveGroup();
75	
76	            $categorySort = 0;
77	            foreach ($blocks as $blockName => $values) {
78	                $category = TagCategory::query()->updateOrCreate(
79	                    ['tag_group_id' => $group->id, 'slug' => Str::slug($blockName)],
80	                    ['name' => ['it' => $blockName, 'en' => $blockName], 'sort' => $categorySort++],
81	                );
82	                $stats['categories']++;
83	
84	                if ($this->option('fresh')) {
85	                    Tag::query()->where('tag_category_id', $category->id)->delete();
86	                }
87	
88	                // tag esistenti indicizzati per nome normalizzato: i già
89	                // presenti restano intatti (nome compreso), i nuovi vengono creati
90	                $existing = Tag::query()
91	                    ->where('tag_category_id', $category->id)
92	                    ->get()
93	                    ->keyBy(function (Tag $tag): string {
94	                        $name = $tag->getTranslation('name', 'it');
95	
96	                        return $this->normalizeTagName(is_string($name) ? $name : '');
97	                    });
98	
99	                foreach ($values as $value) {
100	                    $key = $this->normalizeTagName($value);
101	                    if ($existing->has($key)) {
102	                        $stats['tags']++;
103	
104	                        continue;
105	                    }
106	
107	                    $tag = new Tag();
108	                    $tag->tag_category_id = $category->id;
109	                    $tag->setTranslations('name', ['it' => $value, 'en' => $value]);
110	                    $tag->save();
111	                    $existing->put($key, $tag);
112	                    $stats['tags']++;
113	                }
114	            }
115	        });
116	
117	        $this->info('Import tag materiali completato.');
118	        $this->table(
119	            ['Metrica', 'Valore'],
120	            collect($stats)->map(fn ($v, $k): array => [$k, $v])->values()->all(),
121	        );
122	
123	        return self::SUCCESS;
124	    }
125	
126	    /**
127	     * Legge il foglio Materiali e raggruppa i valori per blocco.
128	     * Ritorna null se il foglio non esiste.
129	     *
130	     * @return array<string, list<string>>|null
131	     */
132	    private function parseSheet(string $file): ?array
133	    {
134	        $blocks = null;
135	        $current = null;
136	
137	        $reader = new Reader();
138	        $reader->open($file);
139	        foreach ($reader->getSheetIterator() as $sheet) {
140	            if ($sheet->getName() !== self::SHEET) {
141	                continue;
142	            }
143	            $blocks = [];
144	
145	            foreach ($sheet->getRowIterator() as $row) {
146	                $cell = $row->getCells()[0] ?? null;
147	                $raw = $cell?->getValue();
148	                $value = is_scalar($raw) ? trim((string) $raw) : '';
149	
150	                // righe vuote e separatori (____) tra i gruppi
151	                if ($value === '' || preg_match('/^_+$/', $value) === 1) {
152	                    continue;
153	                }
154	
155	                $blockName = self::BLOCKS[$this->normalize($value)] ?? null;
156	                if ($blockName !== null) {
157	                    $current = $blockName;
158	                    $blocks[$current] ??= [];
159	
160	                    continue;
161	                }
162	
163	                if ($current === null) {
164	                    $this->warn("Valore fuori da ogni blocco, ignorato: {$value}");
165	
166	                    continue;
167	                }
168	
169	                $blocks[$current][] = $value;
170	            }
171	
172	            break;
173	        }
174	        $reader->close();
175	
176	        return $blocks;
177	    }
178	
179	    /**
180	     * Gruppo tag anagrafica dei materiali Indoor (creato se assente).
181	     * Fallisce se la Category1 "Indoor" non esiste.
182	     */
183	    private function resolveGroup(): TagGroup
184	    {
185	        $indoor = Category1::query()->where('slug', 'indoor')->firstOrFail();
186	
187	        return TagGroup::query()
188	            ->where('entity_type', 'material')
189	            ->where('target', TagTarget::Entity)
190	            ->where('category_1_id', $indoor->id)
191	            ->first()
192	            ?? TagGroup::query()->create([
193	                'entity_type' => 'material',
194	                'target' => TagTarget::Entity,
195	                'category_1_id' => $indoor->id,
196	                'name' => ['it' => 'Filtri Materiali Interior', 'en' => 'Interior material filters'],
197	            ]);
198	    }
199	
200	    private function normalize(string $value): string
201	    {
202	        return trim((string) preg_replace('/\s+/', ' ', mb_strtolower($value)));
203	    }
204	
205	    /**
206	     * Forma canonica del nome tag per il matching: case-insensitive, spazi
207	     * collassati e suffissi tra parentesi ignorati ("Lucido (Glossy)" ≡ "Lucido").
208	     */
209	    private function normalizeTagName(string $value): string
210	    {
211	        return $this->normalize((string) preg_replace('/\s*\([^)]*\)/', ' ', $value));
212	    }
213	}
