\$opaco = \AtrioTeam\DigitalHub\Tags\Models\Tag::whereHas('category', fn(\$q)=>\$q->where('slug','finitura'))->get()->firstWhere(fn(\$t)=>mb_strtolower(\$t->getTranslation('name','it'))==='opaco');
echo 'Lucido materials: '.\$lucido->materials()->count().PHP_EOL;
echo 'Opaco materials: '.\$opaco->materials()->count().PHP_EOL;
